mapper.select:
SELECT c.id, c.article_id, a.title AS article_title, c.user_id, COALESCE(u.username, '访客') AS username, u.avatar AS user_avatar, c.parent_id, pc.content AS parent_content, c.content, c.ip_address, c.status, c.create_time FROM comments c LEFT JOIN articles a ON c.article_id = a.id LEFT JOIN users u ON c.user_id = u.id LEFT JOIN comments pc ON c.parent_id = pc.id WHERE c.deleted = 0
AND c.status = #{status}
AND c.article_id = #{articleId}
AND (c.content ILIKE CONCAT('%', #{keyword}, '%') OR COALESCE(u.username, '访客') ILIKE CONCAT('%', #{keyword}, '%'))
AND c.create_time >= #{startTime}
AND c.create_time <= #{endTime}
ORDER BY c.create_time DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM comments c
WHERE c.deleted = 0

    AND c.status = #{status}


    AND c.article_id = #{articleId}


    AND (c.content ILIKE CONCAT('%', #{keyword}, '%'))


    AND c.create_time >= #{startTime}


    AND c.create_time <= #{endTime}

